// Root observation transport: original shader producer bodies are the only implementation.
use serde::{Deserialize,Serialize};use std::io::{self,Read};
static WARNINGS:std::sync::Mutex<Vec<String>>=std::sync::Mutex::new(Vec::new());struct Observer;static OBSERVER:Observer=Observer;
impl log::Log for Observer{fn enabled(&self,m:&log::Metadata)->bool{m.level()<=log::Level::Warn}fn log(&self,r:&log::Record){if self.enabled(r.metadata()){WARNINGS.lock().unwrap().push(r.args().to_string());}}fn flush(&self){}}
#[derive(Deserialize,Serialize)]struct Input{stops:Vec<[u32;5]>,spread:u8,transform:[u32;6],points_to_unit:[u32;6],opacity:Vec<u32>,color_space:u8,kind:Option<(u8,[u32;2],bool)>,prefix:usize,sentinel:bool,force:bool}
#[derive(Serialize)]struct Output{input:Input,result:Option<(String,Vec<String>,Vec<Vec<u32>>)>,warnings:Vec<String>}
fn main(){log::set_logger(&OBSERVER).unwrap();log::set_max_level(log::LevelFilter::Warn);std::panic::set_hook(Box::new(|_|{}));let mut text=String::new();io::stdin().read_to_string(&mut text).unwrap();let inputs:Vec<Input>=serde_json::from_str(&text).unwrap();let out:Vec<_>=inputs.into_iter().map(|input|{let i=&input;let result=match i.kind{None=>tiny_skia::folia_linear_producer(&i.stops,i.spread,i.transform,i.points_to_unit,&i.opacity,i.color_space,i.prefix,i.sentinel,i.force),Some(kind)=>tiny_skia::folia_radial_producer(&i.stops,i.spread,i.transform,i.points_to_unit,&i.opacity,i.color_space,kind,i.prefix,i.sentinel,i.force)};let warnings=std::mem::take(&mut*WARNINGS.lock().unwrap());Output{input,result,warnings}}).collect();println!("{}",serde_json::to_string(&out).unwrap());}
